import {classifyWasteObject,NON_WASTE_CLASSES} from './waste-rules.js';
import {loadWasteModel} from './waste-model.js';
import {ObjectTracker,coverBox} from './object-tracker.js';
export class LiveARDetector{
 constructor({video,canvas,onDetect=()=>{},onStatus=()=>{},loadModel=loadWasteModel}){Object.assign(this,{video,canvas,onDetect,onStatus,loadModel});this.ctx=canvas.getContext('2d');this.tracker=new ObjectTracker();this.running=false;this.detecting=false;this.epoch=0;this.raf=0;this.input=document.createElement('canvas');this.inputCtx=this.input.getContext('2d');this.lastInference=-Infinity;this.lastDraw=0;this.windowStart=0;this.frames=0;this.fps=0;this.inferenceMs=0;this.signature='';this.nextDrawAt=0;this.checks=0;this.modelStatus='Loading waste detector…';}
 start(){if(this.running)return;this.running=true;const epoch=++this.epoch;this.lastInference=-Infinity;this.lastDraw=0;this.nextDrawAt=0;this.windowStart=0;this.frames=0;this.checks=0;this.modelStatus='Loading waste detector · first download about 29 MB';this.onStatus(this.modelStatus);this.loadModel().then(model=>{if(!this.running||epoch!==this.epoch)return;this.model=model;this.modelStatus='Ready';this.onStatus('Waste detector ready · tags follow visible objects');}).catch(e=>{if(this.running&&epoch===this.epoch){this.modelStatus='Tracking unavailable: '+e.message;this.onStatus(this.modelStatus);}});this.raf=requestAnimationFrame(t=>this.loop(t));}
 stop(){this.running=false;this.epoch++;cancelAnimationFrame(this.raf);this.tracker.clear();this.signature='';this.ctx.clearRect(0,0,this.canvas.width,this.canvas.height);this.onDetect([]);}
 loop(time){if(!this.running)return;if(time<this.nextDrawAt){this.raf=requestAnimationFrame(t=>this.loop(t));return;}if(time-this.nextDrawAt>100)this.nextDrawAt=time;this.nextDrawAt+=1000/60;if(!this.windowStart)this.windowStart=time;const dt=this.lastDraw?time-this.lastDraw:16.7;this.lastDraw=time;this.tracker.smooth(dt);this.render(time);this.frames++;if(time-this.windowStart>1000){this.fps=Math.round(this.frames*1000/(time-this.windowStart));this.frames=0;this.windowStart=time;this.onStatus('LIVE · '+this.fps+' display FPS · '+(this.inferenceMs?this.checks+' checks/s':this.modelStatus));this.checks=0;}
 if(this.model&&!this.detecting&&time-this.lastInference>Math.max(100,this.inferenceMs*.2)&&this.video.readyState>=2&&!this.video.paused){this.lastInference=time;this.detectFrame();}
 this.raf=requestAnimationFrame(t=>this.loop(t));}
 async detectFrame(){if(this.detecting||!this.running)return;this.detecting=true;const epoch=this.epoch,start=performance.now();try{const w=this.video.videoWidth,h=this.video.videoHeight;if(!w||!h)return;const scale=Math.min(1,640/Math.max(w,h));this.input.width=Math.round(w*scale);this.input.height=Math.round(h*scale);this.inputCtx.drawImage(this.video,0,0,this.input.width,this.input.height);const output=await this.model.detect(this.input);if(!this.running||epoch!==this.epoch)return;const detections=[];
 for(const p of output){const key=String(p.class||'').toLowerCase().trim(),info=classifyWasteObject(key);if(NON_WASTE_CLASSES.has(key)||!info.recognized||p.score<.30||!Array.isArray(p.bbox)||!p.bbox.every(Number.isFinite))continue;const b=p.bbox;const box=[b[0]*w/this.input.width,b[1]*h/this.input.height,b[2]*w/this.input.width,b[3]*h/this.input.height];if(box[2]<4||box[3]<4||box[2]*box[3]>w*h*1.05)continue;detections.push({key,info,bbox:box,score:p.score});}
 this.inferenceMs=performance.now()-start;this.tracker.maxAge=Math.max(1200,Math.min(3000,this.inferenceMs*2.5));this.tracker.update(detections,performance.now());this.checks++;
 }catch(e){if(this.running&&epoch===this.epoch){this.tracker.clear();this.onStatus('Detection failed: '+e.message);}}finally{this.detecting=false;}}
 render(now){const rect=this.canvas.parentElement.getBoundingClientRect(),w=rect.width,h=rect.height,dpr=Math.min(devicePixelRatio||1,2);if(this.canvas.width!==Math.round(w*dpr)||this.canvas.height!==Math.round(h*dpr)){this.canvas.width=Math.round(w*dpr);this.canvas.height=Math.round(h*dpr);}const ctx=this.ctx;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const visible=[];
 for(const track of this.tracker.visible(now)){const box=coverBox(track.box,this.video.videoWidth||1,this.video.videoHeight||1,w,h);if(box[0]+box[2]<0||box[1]+box[3]<0||box[0]>w||box[1]>h)continue;this.draw(track,box,w,h);visible.push({...track.info,id:track.id,score:track.score,uncertain:track.score<.55,bbox:box});}
 const signature=visible.map(t=>t.id+':'+t.label+':'+t.uncertain).join('|');if(signature!==this.signature){this.signature=signature;this.onDetect(visible);}}
 draw(track,[x,y,w,h],viewWidth,viewHeight){const ctx=this.ctx,info=track.info;ctx.strokeStyle=info.color;ctx.lineWidth=2;ctx.strokeRect(x,y,w,h);const title=(track.score<.55?'Possible ':'')+info.label,subtitle=track.score<.55?'Verify material · '+info.dustbin:info.dustbin;ctx.font='600 12px system-ui';const width=Math.min(viewWidth-12,Math.max(ctx.measureText(title).width,ctx.measureText(subtitle).width)+20),height=42;const px=Math.max(6,Math.min(viewWidth-width-6,x+w/2-width/2)),py=Math.max(48,Math.min(viewHeight-height-6,y-height-5));ctx.fillStyle='#12221fee';ctx.beginPath();ctx.roundRect(px,py,width,height,7);ctx.fill();ctx.fillStyle=info.color;ctx.fillRect(px,py,3,height);ctx.fillStyle='#fff';ctx.fillText(title,px+9,py+16,width-15);ctx.fillStyle=info.color;ctx.font='600 11px system-ui';ctx.fillText(subtitle,px+9,py+32,width-15);}
}
